sys_ui_action.script:
function confirmDeleteWorkload() {
    var currentSysId = g_form.getUniqueValue();
    var knownToPce = g_form.getValue('known_to_pce');

    if (!currentSysId || !knownToPce || knownToPce === 'unknown') {
        var gm = new GlideModal('', false, 500);
        gm.setTitle('No workloads selected');

        top.window.deleteWorkloadsCallback = function() {
            gm.destroy();
            return false;
        };

        var noSelectionHtml =
            '<div style="padding: 8px 4px 4px 4px; font-size: 16px; line-height: 1.5;">' +
                '<p>No valid workloads selected. Please run this action from an existing Managed or Unmanaged workload.</p>' +
                '<div style="display:flex; justify-content:flex-end; margin-top:20px;">' +
                    '<button style="width: 100%" class="btn btn-default" onclick="top.window.deleteWorkloadsCallback(); return false;">OK</button>' +
                '</div>' +
            '</div>';

        gm.renderWithContent(noSelectionHtml);
        return false;
    }

    function getDeletionType(knownToPce) {
        return knownToPce === "unmanaged" ? "deleted" : "unpaired";
    }

    var gm = new GlideModal('', false, 700);
    gm.setTitle('Confirm selected workload deletion');

    top.window.deleteWorkloadsCallback = function(answer) {
        gm.destroy();

        if (answer === 'yes') {
            var ga = new GlideAjax('IllumioDeletionHandler');
            ga.addParam('sysparm_name', 'deleteSelectedWorkloads');
            ga.addParam('sysparm_checked_sysids', currentSysId);
            ga.getXMLAnswer(function(response) {
                var result = JSON.parse(response);
                if (result.success) {
                    g_form.addInfoMessage(result.message);
                } else {
                    g_form.addErrorMessage(result.message);
                }
            });
        }

        return false;
    };

    var html =
        '<div style="padding: 8px 4px 4px 4px; font-size: 16px; line-height: 1.5;">' +
            '<p>You are about to delete this workload(s) from PCE. Being ' + knownToPce + ' this will be ' + getDeletionType(knownToPce) + ' from PCE.</p>' +
            '<p>It is strongly recommended to run the following a Data Collection before proceeding.</p>' +
            '<p><b>Deletion is a non-reversible action.</b> Click "Yes" to proceed.</p>' +
            '<div style="display:flex; justify-content:flex-end; gap:12px; margin-top:20px;">' +
                '<button style="flex: 1; width: 100%" class="btn btn-default" onclick="top.window.deleteWorkloadsCallback(\'no\'); return false;">Cancel</button>' +
                '<button style="flex: 1; width: 100%" class="btn btn-danger" onclick="top.window.deleteWorkloadsCallback(\'yes\'); return false;">Yes</button>' +
            '</div>' +
        '</div>';

    gm.renderWithContent(html);
    return false;
}
